insert into public.lessons (id,title,description,category,position,lesson_url,published) values ('10000000-0000-4000-8000-000000000001','Real Estate Foundations','Get to know what real estate is, why it matters, and how it shapes the world around us.','core',1,NULL,true) on conflict (id) do nothing;
insert into public.lessons (id,title,description,category,position,lesson_url,published) values ('10000000-0000-4000-8000-000000000002','Real Estate Finance','Discover how money works in real estate, from buying and selling to investing and budgeting.','core',2,NULL,true) on conflict (id) do nothing;
insert into public.lessons (id,title,description,category,position,lesson_url,published) values ('10000000-0000-4000-8000-000000000003','Development & Strategy','Explore how real estate comes to life, from planning and designing to long-term decision making.','core',3,NULL,true) on conflict (id) do nothing;
insert into public.lessons (id,title,description,category,position,lesson_url,published) values ('10000000-0000-4000-8000-000000000004','Careers in Real Estate','See the many exciting paths in real estate, from developers to investors, and learn what it takes to succeed.','core',4,NULL,true) on conflict (id) do nothing;
insert into public.lessons (id,title,description,category,position,lesson_url,published) values ('10000000-0000-4000-8000-000000000005','Entrepreneurship in Real Estate','Learn how to spot opportunities, start projects, and think like a real estate entrepreneur.','bonus',1,NULL,true) on conflict (id) do nothing;
insert into public.lessons (id,title,description,category,position,lesson_url,published) values ('10000000-0000-4000-8000-000000000006','Economics in Real Estate','Explore how supply, demand, and market trends affect real estate and property values.','bonus',2,NULL,true) on conflict (id) do nothing;
insert into public.lessons (id,title,description,category,position,lesson_url,published) values ('10000000-0000-4000-8000-000000000007','Environment & Sustainability','Learn how real estate affects the environment and how sustainable practices can shape greener communities.','bonus',3,NULL,true) on conflict (id) do nothing;
