insert into public.announcements (id,posted_on,title,body,related_section,published) values ('20000000-0000-4000-8000-000000000001','2026-05-05','End of School Workshop!','We recently wrapped up our final real estate presentation and workshop of the school year. We are in the works of planning new events and educational opportunities for the months ahead. Stay tuned for what’s next!',NULL,true) on conflict (id) do nothing;
insert into public.announcements (id,posted_on,title,body,related_section,published) values ('20000000-0000-4000-8000-000000000002','2026-01-26','First In-Person Workshop!','We’re excited to announce we recently hosted our first in-person real estate presentation and workshop, introducing students to the fundamentals of real estate. Stay tuned for future events and workshops!',NULL,true) on conflict (id) do nothing;
insert into public.announcements (id,posted_on,title,body,related_section,published) values ('20000000-0000-4000-8000-000000000003','2025-11-29','First Bonus Module Out Now!','Our first bonus module is now available! Bonus modules provide students the opportunity to explore additional real estate and business topics beyond the core curriculum. More modules are currently in development, so stay tuned for future releases!','bonus',true) on conflict (id) do nothing;
insert into public.announcements (id,posted_on,title,body,related_section,published) values ('20000000-0000-4000-8000-000000000004','2025-10-03','Core Curriculum Now Complete!','We’re excited to announce that our complete self-paced core curriculum is now available, covering the essentials of real estate through four modules. Students can also dive deeper with optional bonus modules exploring entrepreneurship, technology, economics, and more.','core',true) on conflict (id) do nothing;
insert into public.announcements (id,posted_on,title,body,related_section,published) values ('20000000-0000-4000-8000-000000000005','2025-05-29','We’re Now on LinkedIn!','We’re excited to announce that Brillare Scholars is now on LinkedIn! Follow us to stay updated with the latest news, insights, and opportunities from our team.','linkedin',true) on conflict (id) do nothing;
